# Try different groupings
for group_size in range(4, 8):
    text = ''
    for i in range(0, len(ternary) - group_size, group_size):
        chunk = ternary[i:i+group_size]
        val = sum(d * (3 ** (group_size - 1 - j)) for j, d in enumerate(chunk))
        if 32 <= val <= 126:
            text += chr(val)
        elif val == 10:
            text += '\n'

    if any(c.isalpha() for c in text[:50]):
        print(f"\n=== Group size {group_size} ===")
        print(text[:200])

# Strip long runs of same value
import itertools
cleaned = []
for val, group in itertools.groupby(ternary):
    group_list = list(group)
    if len(group_list) < 10 or val == 1:  # Keep short runs and all 1s
        cleaned.extend(group_list)

print(f"Cleaned length: {len(cleaned)}")
print(cleaned[:100])
